async function main(): Promise<void> {
  console.log(`\n${BOLD}${CYAN}===============================================${RESET}`);
  console.log(`${BOLD}${CYAN} Code Ninjas Centre Onboarding: ${centreName}${RESET}`);
  console.log(`${BOLD}${CYAN}===============================================${RESET}`);
  console.log(`  Country: ${country} | Area Code: ${areaCode}`);
  if (ownerName) console.log(`  Owner: ${ownerName} <${ownerEmail}>`);
  if (dryRun) console.log(`  ${YELLOW}${BOLD}MODE: DRY RUN${RESET}`);

  const state: OnboardingState = {
    twilioNumber: null,
    twilioSid: null,
    retellLlmId: null,
    retellAgentId: null,
    retellPhoneId: null,
    cekuraAgentId: null,
    cekuraScenarioLocId: null,
    cekuraScenarioHpId: null,
  };

  const completed: string[] = [];
  const failed: string[] = [];

  // Steps 1-6 are API-dependent and sequential
  const steps: Array<{
    name: string;
    fn: (state: OnboardingState) => Promise<void> | void;
  }> = [
    { name: "Twilio Provision", fn: step1_twilioProvision },
    { name: "Retell LLM", fn: step2_retellLlm },
    { name: "Retell Agent", fn: step3_retellAgent },
    { name: "Retell Phone Import", fn: step4_retellPhone },
    { name: "Cekura Agent", fn: step5_cekuraAgent },
    { name: "Cekura Scenarios", fn: step6_cekuraScenarios },
  ];

  for (const step of steps) {
    try {
      await step.fn(state);
      completed.push(step.name);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      fail(msg);
      failed.push(step.name);

      // Report partial progress and bail
      console.log(`\n${RED}${BOLD}Onboarding ABORTED at step: ${step.name}${RESET}`);
      console.log(`\n  ${GREEN}Completed:${RESET} ${completed.join(", ") || "none"}`);
      console.log(`  ${RED}Failed:${RESET} ${failed.join(", ")}`);

      if (completed.length > 0) {
        console.log(`\n  ${YELLOW}Partial resources created (may need manual cleanup):${RESET}`);
        if (state.twilioNumber) console.log(`    Twilio: ${state.twilioNumber} (SID: ${state.twilioSid})`);
        if (state.retellLlmId) console.log(`    Retell LLM: ${state.retellLlmId}`);
        if (state.retellAgentId) console.log(`    Retell Agent: ${state.retellAgentId}`);
        if (state.retellPhoneId) console.log(`    Retell Phone: ${state.retellPhoneId}`);
        if (state.cekuraAgentId) console.log(`    Cekura Agent: ${state.cekuraAgentId}`);
      }

      process.exit(1);
    }
  }

  // Steps 7-11 are informational (no API calls), always succeed
  step7_cekuraCron(state);
  step8_chatDash(state);
  step9_googleSheet(state);
  step10_hiya(state);
  step11_summary(state);
}

