// Sub-account Twilio helpers — use sub-account credentials
async function subTwilioGet<T>(subSid: string, subToken: string, path: string): Promise<T> {
  const url = `${TWILIO_BASE}/Accounts/${subSid}${path}`;
  const auth = Buffer.from(`${subSid}:${subToken}`).toString("base64");
  const res = await fetch(url, {
    headers: { Authorization: `Basic ${auth}` },
  });
  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Twilio GET (sub) ${path} → ${res.status}: ${body}`);
  }
  return res.json() as Promise<T>;
}

async function subTwilioPost<T>(subSid: string, subToken: string, path: string, formData: Record<string, string>): Promise<T> {
  const url = `${TWILIO_BASE}/Accounts/${subSid}${path}`;
  const auth = Buffer.from(`${subSid}:${subToken}`).toString("base64");
  const body = new URLSearchParams(formData).toString();
  const res = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Basic ${auth}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body,
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Twilio POST (sub) ${path} → ${res.status}: ${text}`);
  }
  return res.json() as Promise<T>;
}

// Twilio Trunking API helpers — uses sub-account credentials
async function trunkingPost<T>(subSid: string, subToken: string, path: string, formData: Record<string, string>): Promise<T> {
  const url = `${TWILIO_TRUNKING_BASE}${path}`;
  const auth = Buffer.from(`${subSid}:${subToken}`).toString("base64");
  const body = new URLSearchParams(formData).toString();
  const res = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Basic ${auth}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body,
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Trunking POST ${path} → ${res.status}: ${text}`);
  }
  return res.json() as Promise<T>;
}

